import csv, json, time, datetime, zipfile
from pathlib import Path
import numpy as np
from contact import P, D, LABELS, sha, write, state

def run():
    st = time.perf_counter()
    m = json.load(open(P / 'raw/INPUT_MANIFEST.json'))
    rows = [json.load(open(P / 'raw/cases' / (c + '.json'))) for c in m['cases']]
    rounds = {k: json.load(open(P / 'raw' / f'RESULTS_{k}.json')) for k in ['R1', 'R2', 'R3']}
    teeth = json.load(open(P / 'raw/RESULTS_TOOTHWISE_R2.json'))
    op = json.load(open(P / 'raw/OPPOSITION_FEATURES_R2.json'))
    reportrows = json.load(open(P / 'raw/COMPARISON_ROWS_R2.json'))
    certs = [json.load(open(p)) for p in sorted((P / 'raw/certificates').glob('*.json'))]
    controls = [r['numerical_control'] for r in rows if 'numerical_control' in r]
    artefacts = []
    for f in sorted(D.rglob('*')):
        if f.is_file():
            artefacts.append(dict(path=str(f), bytes=f.stat().st_size, sha256=sha(f)))
    assert sum((x['bytes'] for x in artefacts)) < 3000000000
    write(P / 'raw/DATA_ARTIFACT_MANIFEST.json', dict(root=str(D), total_bytes=sum((x['bytes'] for x in artefacts)), files=artefacts))
    gaps = np.array([min((x['minimum_projected_gap_mm'] for x in r['pairs'])) for r in rows])
    areas = np.array([r['features']['total_signed_proximity_area_mm2'] for r in rows])
    near = np.array([r['features']['total_absolute_near_area_mm2'] for r in rows])
    pairs = [x for r in rows for x in r['pairs']]
    metrics = dict(cases=len(rows), tooth_pairs_with_projected_overlap=len(pairs), projected_gap_minimum_quantiles_mm=np.quantile(gaps, [0, 0.01, 0.05, 0.25, 0.5, 0.75, 0.95, 1]).tolist(), cases_with_projected_penetration_beyond_0_03mm=int((gaps < -0.03).sum()), cases_with_global_minimum_within_nonpenetrating_proximity_band=int(((gaps >= -0.03) & (gaps <= 0.1)).sum()), cases_without_proximity_at_0_1mm=int((gaps > 0.1).sum()), projected_proximity_area_quantiles_mm2=np.quantile(areas, [0, 0.25, 0.5, 0.75, 1]).tolist(), absolute_near_area_quantiles_mm2=np.quantile(near, [0, 0.25, 0.5, 0.75, 1]).tolist(), near_contact_pairs=sum((p['near_contact_possible_under_offset_scenarios'] for p in pairs)), excess_penetrating_pairs=sum((p['excess_projected_penetration'] for p in pairs)), median_unassigned_upper_face_fraction=float(np.median([1 - r['stats']['upper']['labelled_face_fraction'] for r in rows])), median_unassigned_lower_face_fraction=float(np.median([1 - r['stats']['lower']['labelled_face_fraction'] for r in rows])))
    with (P / 'raw/TOOTH_PAIR_MAP.csv').open('w') as f:
        names = ['case_id', 'upper_fdi', 'lower_fdi', 'minimum_projected_gap_mm', 'minimum_enclosure_lower_mm', 'minimum_enclosure_upper_mm', 'enclosure_round', 'projected_proximity_area_mm2', 'absolute_near_area_mm2', 'penetrating_projected_area_mm2', 'patch_x_mm', 'patch_y_mm', 'physical_status']
        w = csv.DictWriter(f, fieldnames=names)
        w.writeheader()
        for (r, c) in zip(rows, certs):
            assert r['case_id'] == c['case_id']
            tight = P / 'raw/refined_certificates' / (c['case_id'] + '.json')
            chosen = json.load(open(tight)) if tight.exists() else c
            bound_round = 'R4' if tight.exists() else 'R3'
            bounds = {(p['upper_fdi'], p['lower_fdi']): p for p in chosen['pairs']}
            for p in r['pairs']:
                b = bounds[p['upper_fdi'], p['lower_fdi']]
                xy = p['patch_centroid_xy_frame_mm'] or [None, None]
                w.writerow(dict(case_id=r['case_id'], **{k: p[k] for k in ['upper_fdi', 'lower_fdi', 'minimum_projected_gap_mm', 'projected_proximity_area_mm2', 'absolute_near_area_mm2', 'penetrating_projected_area_mm2']}, minimum_enclosure_lower_mm=b['minimum_gap_enclosure_mm'][0], minimum_enclosure_upper_mm=b['minimum_gap_enclosure_mm'][1], enclosure_round=bound_round, patch_x_mm=xy[0], patch_y_mm=xy[1], physical_status='UNKNOWN'))
    discord = {r['case_id'] for r in reportrows if r['report_discordant']}
    panel = sorted(discord, key=lambda c: __import__('hashlib').sha256(('X21-explanation:' + c).encode()).hexdigest())[:8]
    examples = []
    for c in panel:
        examples.append(dict(case_id=c, report_comparisons=[r for r in reportrows if r['case_id'] == c], opposition=op[c], minimum_projected_gap_mm=min((p['minimum_projected_gap_mm'] for p in next((r for r in rows if r['case_id'] == c))['pairs'])), explanation_status='DESCRIPTIVE_GEOMETRY_AND_REPORT_CONFLICT; causal origin UNKNOWN'))
    write(P / 'raw/DISAGREEMENT_EXAMPLES.json', examples)
    costs = dict(geometry_preparation_and_query_wall_s=sum((r['cost']['wall_s'] for r in rows)), geometry_cpu_s=sum((r['cost']['cpu_s'] for r in rows)), continuous_minimum_query_s=sum((r['cost']['minimum_query_s'] for r in rows)), patch_query_s=sum((r['cost']['patch_query_s'] for r in rows)), numerical_refinement_control_s=sum((r['numerical_control']['total_control_s'] for r in rows if 'numerical_control' in r)), peak_rss_MiB=max((r['cost']['peak_rss_MiB'] for r in rows)), fits={k: json.load(open(P / 'raw' / f'FIT_COST_{k}.json')) for k in ['R1', 'R2']}, opposition=json.load(open(P / 'raw/OPPOSITION_COST_R2.json')), certificates=rounds['R3']['costs'], report_evaluation_s={k: rounds[k]['evaluation_wall_s'] for k in ['R1', 'R2']}, discovery_code_reading_and_coding_s=None, independent_lab_validation_s=None, inherited_X11_fit_and_batch_cost='Reused, not zero cost. X11 raw/R4_FIT_COST.json and BATCH_COST_FULL_RUN.json; source development UNKNOWN. Not charged as repeated compute.', queries='Case-level geometry costs retained; report batch query included fit cost.', fallback='UNKNOWN external FDI/point/loaded-bite acquisition cost, no fabricated force estimate.', full_cost_claim='UNKNOWN; no 10x or cost superiority claim.')
    res = dict(lane='X21-contact-map', claim_type='capability', review_state='PENDING_INDEPENDENT_REVIEW', updated_utc=datetime.datetime.now(datetime.timezone.utc).isoformat(), capability='993 source-traceable tooth-pair projected geometry maps + opposition candidates + categorical report comparison + rational-witness/minimum enclosures', external_referent=rounds['R1']['external_referent'], rounds=rounds, toothwise_crossbite=teeth, population_geometry=metrics, physical_certified_contact_map='UNKNOWN_NOT_ESTABLISHED: no independent contact/area/pose/FDI measurements', numeric_overbite_overjet_Angle_accuracy='UNKNOWN: named points are X11 hypotheses, no mm landmark truth', geometry_explains_clinician_disagreement='Descriptive associations only; per-field preregistered entropy-AUC diagnostic in rounds, no causal attribution', control_outcome='Full-pair/subset/witness numeric oracles and exact/AABB certificates agree in scoped tests; no algorithm superiority claim', costs=costs, large_arrays=dict(root=str(D), total_bytes=sum((x['bytes'] for x in artefacts)), manifest='raw/DATA_ARTIFACT_MANIFEST.json', manifest_sha256=sha(P / 'raw/DATA_ARTIFACT_MANIFEST.json')), failed_gates_preserved=True, source_dataset_license='Bite2Text exact terms UNKNOWN; official page no explicit license; private local use, no raw-data redistribution', upstream_model_dataset_license='Teeth3DS official challenge repo CC BY-NC-ND4.0; local snapshot mapping unresolved, see X11. No Teeth3DS meshes used/exported in X21.')
    write(P / 'results.json', res)
    fields = rounds['R1']['fields']
    table = ['| Quantity | Contact R1 : balanced hit | Opposition R2 | X7 | R2 quantity coverage | R2 quantity size |', '|---|---:|---:|---:|---:|---:|']
    for field in fields:
        a = rounds['R1']['fields'][field]
        b = rounds['R2']['fields'][field]
        table.append(f"| {field} | {a['first_report']['balanced_accuracy']:.3f} | {b['first_report']['balanced_accuracy']:.3f} | {b['x7_first_report']['balanced_accuracy']:.3f} | {b['all_report_set_coverage']:.3f} | {b['mean_set_size']:.2f} |")
    tab = '\n'.join(table)
    r3 = rounds['R3']
    summary = f"# Per tooth contact geometry and bite reports\n\nRun `./run_all.sh` . Figure: [figures/contact_report_demo.png](figures/contact_report_demo.png). CSV: [raw/TOOTH_PAIR_MAP.csv](raw/TOOTH_PAIR_MAP.csv). For your own registered pair of X11 labels, see `python3 code/demo_case.py --help` . No data is retrieved; everything is read from local ZIP members.\n\nThe idea is to tie each geometric gap to tooth pairs, source triangles and a controllable uncertainty. **{len(rows)} scan pairs** have maps with {len(pairs):,} projected overlapping tooth pairs. Minimagap has rationally calculated witnesses and conservative lower bounds on the rounded mesh model. Physical contact is still unknown.\n\nClinically reference is [Bite2Text ](https://ditto.ing.unimore.it/bite2text/), the already existing English IOS reports in`{m['zip']}::*/reports_ios_en/*.txt`. This applies to categories and named crucifix teeth; the reports do not measure area, gap or point coordinates. Precise members and SHA256 are in the comparator lines. X7 : s patient sharing is re-used: 593 training, 198 calibration , 198 test. These test cases have already been reviewed in X7 / X11 ; the result here is a frozen descriptive re-evaluation, no untouched external test cohort.\n\n{tab}\n\nFrozen Weekend Runner: R1 **{rounds['R1']['primary_gate']}**, R2 **{rounds['R2']['primary_gate']}**. Per tooth reversed order against explicit named crossbit: recall {teeth['named_tooth_recall']:.3f}, specificity of explicit absence reports {teeth['absence_specificity']:.3f}; gate **{teeth['primary_gate']}**. Positive reports can list incomplete tooth amounts; unlisted teeth is not safe negative.\n\nCertifikat R3: {r3['valid_enclosures']:,}/{r3['n_pairs']:,} giltiga intervall; medianbredd {r3['interval_width_quantiles_mm'][2]:.4f} mm, andel ≤0,20 mm {r3['fraction_width_le_0_20mm']:.3f}; usability gate **{r3['primary_gate']}**. Rational witness proves an upper boundary for the minimum gap; the lower value comes from all AABB-overlapping triangles. This applies to projected affee geometry with calculated FDI . Numerical controls : 12 frozen case, maximum parity error {rounds['R1']['maximum_numerical_parity_mm']:.3g} mm ; injected gap, categories and lower bounds rejected.\n\nWhat does not holds : **{metrics['cases_with_projected_penetration_beyond_0_03mm']}/{len(rows)}** source poses have projected overlap > 0,03 mm . Negative gap cannot be made to physical contact area or force. Rasterarea is projection at 0,10 mm bands, with separate 0,2 → 0,1 mm panel control; the range at ± 0,05 mm pose displacement is a declared scenario, no measured scanner safety. FDI , named cusp/groove and anatomical axes are not validated on Bite2Text . Overbite/overjet and Angle are candidate measures, not certified clinical diagnosis. The linguistics' disagreements may be category boundaries, different observations, translation, parser or geometry; the reason is not identified.\n\nContact edges alone lack M1 proximity at {teeth['contact_only_missing_M1_relationships']['no_proximal_M1_edge']}/{teeth['contact_only_missing_M1_relationships']['described_M1_sides']} described M1 pages and central incisiveness on {teeth['contact_only_missing_anterior_relationships']['no_central_incisor_proximity_edge']}/{teeth['contact_only_missing_anterior_relationships']['described_overjet_cases']} A hit-and-run. Therefore, R2 retains the opposing points even without contact.\n\nKostnad: kartbyggande {costs['geometry_preparation_and_query_wall_s']:.1f} s, numeriska panelkontroller extra {costs['numerical_refinement_control_s']:.1f} s, certifikatrundan {costs['certificates']['total_wall_s']:.1f} s; max kart-RSS {costs['peak_rss_MiB']:.1f} MiB. Fit/query and all re-uses are separately reported in results.json. Code/source search cost and external lab measurement UNKNOWN ; no 10 x-claim. Dataarrayer {res['large_arrays']['total_bytes'] / 1000000.0:.1f} MB on the data drive, SHA256 in manifest. ≤ 4 threads, no GPU .\n\nLicense: Bite2Text ZIP lacks README/LICENSE and the author page specifies no explicit data license; exact condition **UNKNOWN**. Private local research, no raw material publishing. X11 : s model is trained on Teeth3DS : official challenge-repot indicates CC BY-NC-ND 4.0 for data, but the local snapshot binding is not clear. No Teeth3DS -mesher is read or exported here. Second dataset is not used. Source code is local reuse with sourcehashar; no license reclassification. Deidentified cases- ID , no photos or personal data are exported.\n\nNext testable design: separate independent tooth -/point marking on frozen 12 -fall panel and registered loaded bite with contact film/ pressure image and repeated scan . The predictions are already frozen in FROZEN_PREDICTIONS *.json and MATCHED_MEASUREMENT_SPEC.md describe the observations. Resultatstatus PENDING_INDEPENDENT_REVIEW.\n"
    (P / 'README_DEMO.md').write_text(summary)
    (P / 'RESULTS.md').write_text(summary + '\nRaw gates and versions: PREREG_R1 / R2 / R3 , raw/RESULTS_R1/R2/R3 , raw/RESULTS_TOOTHWISE_R2. No failed gate modified.\n')
    write(P / 'raw/PLOT_DATA.json', dict(fields=fields, r1=rounds['R1'], r2=rounds['R2'], r3=rounds['R3'], geometry=metrics, toothwise=teeth, case=m['numerical_panel'][0], case_map_path=str(D / 'maps' / (m['numerical_panel'][0] + '.npz')), case_row_path=str(P / 'raw/cases' / (m['numerical_panel'][0] + '.json')), opposition=op, reportrows=reportrows))
    (P / 'HANDOFF.md').write_text(f"X21-contact-map — PENDING_INDEPENDENT_REVIEW\n\nCapability : {len(rows)} dental projected gap/patch maps, per-pair source witnesses, opposition in case of missing contact, clinician report comparisons, conservative rational gap intervals. Run ./run_all.sh . R1 reportgrind {rounds['R1']['primary_gate']}; R2 {rounds['R2']['primary_gate']}; per tooth cross bite {teeth['primary_gate']}; R3 intervallgrind {r3['primary_gate']}. Precise values in results.json and README_DEMO.md.\n\nWhat failed : physical contact certification has no patient connected reference . {metrics['cases_with_projected_penetration_beyond_0_03mm']}/{len(rows)} source poses show projected gap < − 0,03 mm. FDI , MB -cush/groove and axis on Bite2Text UNKNOWN . The contact graph is not sufficient for bite diagnosis; separated teeth requires opposition geometry. Clinical millimetre accuracy UNKNOWN, report associations not point truth. Previous X7 test cohort is reused, not untouched validation. Range width and report gates are preserved.\n\nRounds finished without gate-tuning. R2 changed the representation by keeping non-contact points. R3 changed the certificate from numerical compliance to conservative inclusion with exact-rational feasible wisdom. Both leave unknow physical leaves open. The next construction is narrower geometric sub-limitations with adaptive triangle division where the interval intersects the proximity band; at the same time, external FDI -/named point-measurements and a loaded registered bite according to MATCHED_MEASUREMENT_SPEC.md are needed. No simulated parameter values may replace the observations.\n\nGraph saknar matching quantity target. Suggestion DENT - VAL - BITE2TEXT - TOOTH - CONTACT - REPORT : smooth-resolved registered-pose geometry + clinician categories; no force-target. GRAPH_FEEDBACK.json is PENDING_INDEPENDENT_REVIEW, no dispatch/feedbackreceipt or sourceadmission. Native/generated graphs untouched.\n\nSource ZIP streamed, X7 / X11 /P/ X2 read only; no sub-agents, clinical advice, email, push. Arrayer `{D}`, {res['large_arrays']['total_bytes']} byte, manifesthash {res['large_arrays']['manifest_sha256']}. Not more than 3 GB even for fresh replay. All failures COMMANDS.md /raw logs. No own processes shall be left uncontrolled at completion.\n")
    feedback = dict(target_id=None, proposed_target_id='DENT-VAL-BITE2TEXT-TOOTH-CONTACT-REPORT', review_state='PENDING_INDEPENDENT_REVIEW', coverage_status='MISSING_MATCHING_QUANTITY', result_file='results/LANE_X21_CONTACT_MAP/results.json', sha256=sha(P / 'results.json'), measured_quantity='Tooth-pair projected gap enclosure, patch area, report categorical agreement and report disagreement', units=['mm', 'mm2', 'fraction'], uncertainty='Conditional rounded labelled mesh, hypothetical pose/point error scenarios; physical/target anatomy UNKNOWN', population_regime='993 Bite2Text nonempty registered scan pairs, inherited593/198/198 X7 partition; legacy-test reuse', preregistered_gate=['PREREG_R1.json', 'PREREG_R2.json', 'PREREG_R3.json'], baseline='Exhaustive numerical pair controls; stored X7 answer-level comparison; no algorithm contest', outcome=f"R1 {rounds['R1']['primary_gate']}; R2 {rounds['R2']['primary_gate']}; crossbite {teeth['primary_gate']}; R3 {r3['primary_gate']}; physical anatomical certification UNKNOWN", negative_result=True, missing_coverage_reason='Existing regional bite-force node is a different quantity; lookup report target absent/conflicting. Explicit coverage proposal only; no canonical/generated graph mutation.')
    write(P / 'GRAPH_FEEDBACK.json', feedback)
    write(P / 'raw/PACKAGE_COST.json', dict(wall_s=time.perf_counter() - st))
    state('PACKAGED_PENDING_REVIEW', 'Completed maps and preserved R1/R2/R3 outcomes', 'Run meaningful artifact checks and figure, freeze next-measurement port')
if __name__ == '__main__':
    run()
